sp_widget.css:
.pt-help__h { margin: 0 0 10px; font-size: var(--pt-fs-md); color: var(--pt-text-hi); font-weight: 650; }
.pt-help__legend { display: flex; flex-direction: column; gap: 16px; }
.pt-help__row { display: flex; align-items: flex-start; gap: 16px; }
.pt-help__demo { flex: 0 0 132px; display: flex; align-items: center; justify-content: flex-start; padding-top: 2px; }
.pt-help__none { font-size: 11.5px; color: var(--pt-text-faint); font-style: italic; }
.pt-help__t { font-size: 13.5px; font-weight: 600; color: var(--pt-text-hi); margin-bottom: 3px; }
.pt-help__s { font-size: 13px; color: var(--pt-text-mute); line-height: 1.62; }
.pt-help__steps { margin: 0; padding-left: 20px; color: var(--pt-text-mute); font-size: 13.5px; line-height: 1.68; }
.pt-help__steps li { margin-bottom: 10px; }
.pt-help__steps b, .pt-help__list b { color: var(--pt-text-hi); }
.pt-help__list { margin: 0; padding-left: 20px; color: var(--pt-text-mute); font-size: 13.5px; line-height: 1.68; }
.pt-help__list li { margin-bottom: 8px; }
.pt-help__chips { display: flex; flex-wrap: wrap; gap: 8px; }
.pt-help__steps code, .pt-help__list code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 12px; padding: 1px 6px; border-radius: 5px;
  background: rgba(255,255,255,.06); color: var(--pt-text-hi);
}
@media (max-width: 620px) {
  .pt-help__row { flex-direction: column; gap: 8px; }
  .pt-help__demo { flex: none; }
}
